using System;
using System.Linq;
using UnityEngine;

namespace Imoni.Game.World
{
    /// <summary>References generated by ImoniSetup. Runtime code never creates replacement art or prefabs.</summary>
    public sealed class WorldRuntimeAssets : ScriptableObject
    {
        public WorldTileSet tileSet;
        public ResourceNodeView resourceNode;
        public CharacterView character;
        public GatherPopupView gatherPopup;
        public LockedAreaOverlayView lockedAreaOverlay;
        public ResourceArt[] resources = Array.Empty<ResourceArt>();
        public Sprite stump;
        public Sprite circle;
        public Sprite camp;
        public Sprite[] avatarLayers = Array.Empty<Sprite>();
        public ResourceArt Resource(string materialId) => resources.First(item => item.materialId == materialId);
    }

    [Serializable]
    public sealed class ResourceArt
    {
        public string materialId;
        public Sprite sprite;
        public Color tint = Color.white;
        public string label;
    }
}
